// Fails if a tracked or new source file contains a value that looks like a real credential.
// This is a guard rail, not a complete secret scanner. Run it in CI with a dedicated scanner before any production release.
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join, relative, resolve } from "node:path";

const root = resolve(import.meta.dirname, "..");
// supabase/.temp holds runtime credentials generated by `supabase start`. It is git-ignored and must never be committed.
// build, .gradle and .cxx are generated native build output under apps/mobile/android (git-ignored).
const SKIP_DIRS = new Set(["node_modules", ".next", ".expo", "dist", "coverage", "test-results", "playwright-report", ".git", ".temp", "build", ".gradle", ".cxx"]);
const SKIP_FILES = new Set(["pnpm-lock.yaml", "package-lock.json"]);

const PATTERNS = [
  { name: "private key block", regex: /-----BEGIN (RSA |EC |OPENSSH |)PRIVATE KEY-----/ },
  { name: "Supabase service role / secret key", regex: /\bsb_secret_[A-Za-z0-9_-]{10,}/ },
  { name: "Supabase service JWT", regex: /eyJ[A-Za-z0-9_-]{10,}\.eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/ },
  { name: "Google API key", regex: /\bAIza[0-9A-Za-z_-]{30,}/ },
  { name: "AWS access key id", regex: /\bAKIA[0-9A-Z]{16}\b/ },
  { name: "Razorpay-style live key", regex: /\brzp_live_[A-Za-z0-9]{10,}/ },
  { name: "assigned secret literal", regex: /(SECRET|PASSWORD|API_KEY|TOKEN)\s*[:=]\s*["'][A-Za-z0-9/+_=-]{16,}["']/i }
];

function* walk(dir) {
  for (const entry of readdirSync(dir)) {
    if (SKIP_DIRS.has(entry)) continue;
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) yield* walk(full);
    else if (!SKIP_FILES.has(entry)) yield full;
  }
}

const findings = [];
for (const file of walk(root)) {
  const rel = relative(root, file);
  // Only text-like source and configuration files are scanned.
  if (!/\.(ts|tsx|js|mjs|cjs|json|md|toml|sql|yml|yaml|env|example|txt|css|html)$/.test(rel) && !rel.includes(".env")) continue;
  const text = readFileSync(file, "utf8");
  for (const { name, regex } of PATTERNS) {
    if (regex.test(text)) findings.push(`${rel}: ${name}`);
  }
}

if (findings.length > 0) {
  console.error("Possible secrets found:");
  for (const finding of findings) console.error(`  - ${finding}`);
  process.exit(1);
}
console.info("secrets check: no credential-like values found in scanned files");
